// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CiPermission) predicate.CiPermission {
	return predicate.CiPermission(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CiPermission) predicate.CiPermission {
	return predicate.CiPermission(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CiPermission) predicate.CiPermission {
	return predicate.CiPermission(sql.NotPredicates(p))
}
